import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Webhooks & Alerts","description":"Sentinel alert channels — Discord embeds, a generic JSON webhook, and SMTP email via the panel mailer — with per-channel minimum severity, cooldown and rate limiting.","frontmatter":{"title":"Webhooks & Alerts","description":"Sentinel alert channels — Discord embeds, a generic JSON webhook, and SMTP email via the panel mailer — with per-channel minimum severity, cooldown and rate limiting."},"headers":[],"relativePath":"pterodactyl-sentinel/user-guide/webhooks.md","filePath":"pterodactyl-sentinel/user-guide/webhooks.md","lastUpdated":null}'),s={name:"pterodactyl-sentinel/user-guide/webhooks.md"};function n(r,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="webhooks-alerts" tabindex="-1">Webhooks &amp; Alerts <a class="header-anchor" href="#webhooks-alerts" aria-label="Permalink to &quot;Webhooks &amp; Alerts&quot;">​</a></h1><p>Alerts are dispatched <strong>panel-side only</strong>. When an event batch arrives at <code>POST /api/sentinel/node/events</code>, the panel evaluates each event against the configured channels and sends notifications. Nodes never see webhook URLs, SMTP credentials or recipients — those secrets live exclusively in the panel database (<code>sentinel_settings</code> under the <code>alerts</code> key).</p><p>Three channels, configured under <strong>Sentinel → Settings → Alert Channels</strong>. Each has an enable switch, a destination, and a <strong>minimum severity</strong>: the channel only fires for events at or above that severity.</p><hr><h2 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h2><p>Rich embed alerts to a Discord channel.</p><ol><li>In Discord: channel settings → Integrations → Webhooks → <strong>New Webhook</strong>, copy the URL.</li><li>In the panel: Settings → Alert Channels → enable <strong>Discord</strong>, paste the URL, pick a <code>min_severity</code> (default <code>high</code>), save.</li></ol><p>The URL is validated server-side and must match <code>https://(canary.|ptb.)?discord(app)?.com/api/webhooks/…</code> — a non-Discord URL is rejected with a validation error.</p><p>Each alert is an embed containing the event title, severity (color-coded), category and detector, the attributed server and node, process/path detail, actions taken, and a dry-run marker when applicable.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep Discord at <code>high</code> or <code>critical</code>. At <code>medium</code> you will see every port scan and zip-bomb ratio hit — noisy on a busy fleet.</p></div><h2 id="generic-json-webhook" tabindex="-1">Generic JSON webhook <a class="header-anchor" href="#generic-json-webhook" aria-label="Permalink to &quot;Generic JSON webhook&quot;">​</a></h2><p>POSTs the event as JSON to any <code>http(s)://</code> endpoint — for Slack bridges, PagerDuty, Grafana OnCall, ntfy, or your own automation.</p><ol><li>Enable <strong>Webhook</strong>, paste the endpoint URL, pick <code>min_severity</code> (default <code>high</code>), save.</li><li>Your endpoint receives a JSON POST per qualifying event with the event fields: <code>uuid</code>, <code>occurred_at</code>, <code>category</code>, <code>detector</code>, <code>severity</code>, <code>title</code>, server/node attribution, <code>process</code>, <code>path</code>, <code>evidence</code>, <code>actions_taken</code>, and <code>dry_run</code>.</li></ol><p>Minimal receiver for testing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># on any reachable host</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># (or use a request-bin service to inspect the payload shape)</span></span></code></pre></div><h2 id="smtp-email" tabindex="-1">SMTP email <a class="header-anchor" href="#smtp-email" aria-label="Permalink to &quot;SMTP email&quot;">​</a></h2><p>Sends alert email through the panel&#39;s configured mailer — Sentinel uses whatever mail transport the panel already has (<code>MAIL_*</code> in the panel <code>.env</code>: SMTP, Mailgun, SES, …). There is no separate Sentinel SMTP configuration.</p><ol><li>Make sure panel mail works first (a working &quot;forgot password&quot; email is the proof).</li><li>Enable <strong>SMTP</strong>, enter <strong>recipients</strong> as a space- or comma-separated list — every address is validated and the save fails on the first invalid one.</li><li>Pick <code>min_severity</code> (default <code>critical</code> — email is the noisiest channel to read, so it defaults to the quietest setting).</li></ol><hr><h2 id="severity-filtering-cooldown-and-rate-limiting" tabindex="-1">Severity filtering, cooldown and rate limiting <a class="header-anchor" href="#severity-filtering-cooldown-and-rate-limiting" aria-label="Permalink to &quot;Severity filtering, cooldown and rate limiting&quot;">​</a></h2><p>Alerts are subject to three independent gates, in order:</p><ol><li><strong>Per-channel <code>min_severity</code>.</strong> An event below the channel&#39;s threshold is never sent there. Severity ranks: <code>low</code> &lt; <code>medium</code> &lt; <code>high</code> &lt; <code>critical</code>; the threshold is inclusive.</li><li><strong>Cooldown.</strong> Repeat notifications for the same target are suppressed within the cooldown window, so a miner re-firing every cooldown period does not produce a message per detection.</li><li><strong>Rate limit + batching.</strong> Outbound alerts are rate-limited and batched so a detection storm (say, a fleet-wide volume scan finding hundreds of files) produces a digest rather than hundreds of Discord posts — and Discord&#39;s own webhook rate limits are not tripped.</li></ol><p><strong>Muted servers</strong> (<code>whitelist.servers</code>, or the mute toggle on the Servers tab) suppress alerts entirely while still recording events. <strong>Dry-run</strong> events are marked as such in the message rather than suppressed — you see exactly what would have been enforced.</p><hr><h2 id="recommended-starting-setup" tabindex="-1">Recommended starting setup <a class="header-anchor" href="#recommended-starting-setup" aria-label="Permalink to &quot;Recommended starting setup&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>min_severity</th><th>Why</th></tr></thead><tbody><tr><td>Discord</td><td><code>high</code></td><td>kills, quarantines, escapes — the stuff you want to see same-day</td></tr><tr><td>Webhook</td><td><code>high</code></td><td>feed your automation/ticketing</td></tr><tr><td>SMTP</td><td><code>critical</code></td><td>only miners at full tilt, escapes, confirmed malware — things worth waking someone up</td></tr></tbody></table><p>Watch the feed for a week in dry-run, then adjust. If a channel feels noisy, raise its severity before you disable it — the graduated defaults are tuned so <code>high</code> and up is almost always actionable.</p>`,27)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
